begin;
create table if not exists public.network_organizations (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id), organization_type text not null check (organization_type in ('buyer','seller','both','platform')), legal_name text not null, tax_identifier text, country_code text not null default 'AE' check (length(country_code)=2), active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.network_contracts (id uuid primary key default gen_random_uuid(), buyer_business_id uuid not null references public.businesses(id), seller_business_id uuid not null references public.businesses(id), contract_number text not null unique, currency text not null default 'AED', status text not null default 'draft' check (status in ('draft','active','suspended','expired','terminated')), effective_at timestamptz, expires_at timestamptz, terms jsonb not null default '{}'::jsonb, created_by uuid references auth.users(id), created_at timestamptz not null default now(), check (buyer_business_id <> seller_business_id), check (expires_at is null or effective_at is null or expires_at > effective_at));
create table if not exists public.network_contract_lines (id uuid primary key default gen_random_uuid(), contract_id uuid not null references public.network_contracts(id) on delete cascade, buyer_business_id uuid not null references public.businesses(id), seller_business_id uuid not null references public.businesses(id), ingredient_id uuid references public.ingredients(id), product_id uuid references public.products(id), unit text not null, agreed_quantity numeric(24,8) check (agreed_quantity is null or agreed_quantity > 0), unit_price_minor bigint not null default 0 check (unit_price_minor >= 0), currency text not null default 'AED', terms jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), check ((ingredient_id is not null) <> (product_id is not null)));
create table if not exists public.network_sales_orders (id uuid primary key default gen_random_uuid(), contract_id uuid references public.network_contracts(id), buyer_business_id uuid not null references public.businesses(id), seller_business_id uuid not null references public.businesses(id), order_number text not null unique, currency text not null default 'AED', status text not null default 'draft' check (status in ('draft','submitted','accepted','dispatched','partially_delivered','delivered','cancelled','disputed')), requested_at timestamptz not null default now(), accepted_at timestamptz, total_minor bigint not null default 0 check (total_minor >= 0), notes text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), check (buyer_business_id <> seller_business_id));
create table if not exists public.network_sales_order_lines (id uuid primary key default gen_random_uuid(), sales_order_id uuid not null references public.network_sales_orders(id) on delete cascade, contract_line_id uuid references public.network_contract_lines(id), buyer_business_id uuid not null references public.businesses(id), seller_business_id uuid not null references public.businesses(id), ingredient_id uuid references public.ingredients(id), product_id uuid references public.products(id), quantity numeric(24,8) not null check (quantity > 0), unit text not null, unit_price_minor bigint not null check (unit_price_minor >= 0), line_total_minor bigint generated always as (((quantity * unit_price_minor)::numeric)::bigint) stored, created_at timestamptz not null default now(), check ((ingredient_id is not null) <> (product_id is not null)));
create table if not exists public.network_order_dispatches (id uuid primary key default gen_random_uuid(), sales_order_id uuid not null references public.network_sales_orders(id), buyer_business_id uuid not null references public.businesses(id), seller_business_id uuid not null references public.businesses(id), dispatch_number text not null unique, status text not null default 'planned' check (status in ('planned','confirmed','in_transit','delivered','cancelled','exception')), origin_location_id uuid references public.locations(id), destination_location_id uuid references public.locations(id), dispatched_at timestamptz, expected_at timestamptz, delivered_at timestamptz, evidence jsonb not null default '{}'::jsonb, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.network_order_dispatch_lines (id uuid primary key default gen_random_uuid(), dispatch_id uuid not null references public.network_order_dispatches(id) on delete cascade, sales_order_line_id uuid not null references public.network_sales_order_lines(id), buyer_business_id uuid not null references public.businesses(id), seller_business_id uuid not null references public.businesses(id), quantity numeric(24,8) not null check (quantity > 0), unit text not null, batch_reference text, created_at timestamptz not null default now());
create table if not exists public.network_audit_stream (id bigint generated always as identity primary key, event_type text not null, dispatch_id uuid references public.network_order_dispatches(id), contract_id uuid references public.network_contracts(id), buyer_business_id uuid references public.businesses(id), seller_business_id uuid references public.businesses(id), actor_user_id uuid references auth.users(id), payload jsonb not null default '{}'::jsonb, previous_hash text, signature_block jsonb, event_hash text not null, created_at timestamptz not null default now());
create index if not exists idx_network_contracts_buyer on public.network_contracts(buyer_business_id); create index if not exists idx_network_contracts_seller on public.network_contracts(seller_business_id); create index if not exists idx_network_orders_buyer on public.network_sales_orders(buyer_business_id); create index if not exists idx_network_orders_seller on public.network_sales_orders(seller_business_id); create index if not exists idx_network_dispatches_order on public.network_order_dispatches(sales_order_id); create index if not exists idx_network_audit_created on public.network_audit_stream(created_at,id);
create or replace function public.nos_hash_payload(p_payload jsonb,p_previous text) returns text language sql immutable security invoker set search_path=public,extensions,pg_temp as $$ select encode(extensions.digest(coalesce(p_previous,'')||'|'||p_payload::text,'sha256'),'hex') $$;
create or replace function public.nos_append_audit(p_event_type text,p_dispatch_id uuid default null,p_contract_id uuid default null,p_buyer_business_id uuid default null,p_seller_business_id uuid default null,p_actor_user_id uuid default null,p_payload jsonb default '{}'::jsonb,p_signature_block jsonb default null) returns bigint language plpgsql security definer set search_path=public,extensions,pg_temp as $$ declare v_prev text; v_hash text; v_id bigint; begin if auth.role() not in ('service_role','authenticated') and current_user <> 'postgres' then raise exception 'network audit authorization denied'; end if; select event_hash into v_prev from public.network_audit_stream order by id desc limit 1 for update; v_hash:=public.nos_hash_payload(coalesce(p_payload,'{}'::jsonb),v_prev); insert into public.network_audit_stream(event_type,dispatch_id,contract_id,buyer_business_id,seller_business_id,actor_user_id,payload,previous_hash,signature_block,event_hash) values(p_event_type,p_dispatch_id,p_contract_id,p_buyer_business_id,p_seller_business_id,p_actor_user_id,coalesce(p_payload,'{}'::jsonb),v_prev,p_signature_block,v_hash) returning id into v_id; return v_id; end $$;
alter table public.network_organizations enable row level security; alter table public.network_contracts enable row level security; alter table public.network_contract_lines enable row level security; alter table public.network_sales_orders enable row level security; alter table public.network_sales_order_lines enable row level security; alter table public.network_order_dispatches enable row level security; alter table public.network_order_dispatch_lines enable row level security; alter table public.network_audit_stream enable row level security;
create policy network_org_member_select on public.network_organizations for select to authenticated using (exists(select 1 from public.business_members bm where bm.business_id=network_organizations.business_id and bm.user_id=auth.uid()));
create policy network_contract_member_select on public.network_contracts for select to authenticated using (exists(select 1 from public.business_members bm where bm.business_id=network_contracts.buyer_business_id and bm.user_id=auth.uid()) or exists(select 1 from public.business_members bm where bm.business_id=network_contracts.seller_business_id and bm.user_id=auth.uid()));
create policy network_contract_line_member_select on public.network_contract_lines for select to authenticated using (exists(select 1 from public.business_members bm where (bm.business_id=network_contract_lines.buyer_business_id or bm.business_id=network_contract_lines.seller_business_id) and bm.user_id=auth.uid()));
create policy network_order_member_select on public.network_sales_orders for select to authenticated using (exists(select 1 from public.business_members bm where (bm.business_id=network_sales_orders.buyer_business_id or bm.business_id=network_sales_orders.seller_business_id) and bm.user_id=auth.uid()));
create policy network_order_line_member_select on public.network_sales_order_lines for select to authenticated using (exists(select 1 from public.business_members bm where (bm.business_id=network_sales_order_lines.buyer_business_id or bm.business_id=network_sales_order_lines.seller_business_id) and bm.user_id=auth.uid()));
create policy network_dispatch_member_select on public.network_order_dispatches for select to authenticated using (exists(select 1 from public.business_members bm where (bm.business_id=network_order_dispatches.buyer_business_id or bm.business_id=network_order_dispatches.seller_business_id) and bm.user_id=auth.uid()));
create policy network_dispatch_line_member_select on public.network_order_dispatch_lines for select to authenticated using (exists(select 1 from public.business_members bm where (bm.business_id=network_order_dispatch_lines.buyer_business_id or bm.business_id=network_order_dispatch_lines.seller_business_id) and bm.user_id=auth.uid()));
create policy network_audit_member_select on public.network_audit_stream for select to authenticated using (exists(select 1 from public.business_members bm where (bm.business_id=network_audit_stream.buyer_business_id or bm.business_id=network_audit_stream.seller_business_id) and bm.user_id=auth.uid()));
revoke insert,update,delete on public.network_organizations,public.network_contracts,public.network_contract_lines,public.network_sales_orders,public.network_sales_order_lines,public.network_order_dispatches,public.network_order_dispatch_lines,public.network_audit_stream from anon,authenticated;
grant execute on function public.nos_hash_payload(jsonb,text) to authenticated,service_role; grant execute on function public.nos_append_audit(text,uuid,uuid,uuid,uuid,uuid,jsonb,jsonb) to service_role;
commit;